import java.util.concurrent.atomic.AtomicInteger;
import java.util.zip.CRC32C;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.nativerdf.ValueStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreWalUtf8HashTest {

	@TempDir
	Path directory;

	@Test
	void hashesMatchFullUtf8EncodingAcrossBufferBoundaries() throws Exception {
		List<String> labels = List.of(
				"a".repeat(8_191) + "\uD83D\uDE00" + "end",
				"plain ASCII",
				"a".repeat(8_190) + "\uD83D\uDE00" + "tail",
				"",
				"\u00e9".repeat(4_095) + "\uD83D\uDE00" + "multi-byte",
				"\u20ac".repeat(2_730) + "\uD83D\uDE00" + "three-byte",
				"\u00e9\u6f22\u5b57\uD83D\uDE00".repeat(2_500),
				"a".repeat(1_024),
				"b".repeat(1_025),
				"\u20ac".repeat(8_192) + "multiple-buffers");
		assertMintedHashes(labels);
	}

	@Test
	void malformedSurrogatesUseTheSameReplacementAsStringGetBytes() throws Exception {
		List<String> labels = List.of(
				"a".repeat(8_191) + "\uD800" + "high",
				"a".repeat(8_191) + "\uDC00" + "low",
				"a".repeat(8_191) + "\uD800",
				"\uD800" + "b".repeat(9_000),
				"\uDC00" + "c".repeat(9_000),
				"\uD800\uD800\uDC00\uDC00".repeat(2_500));
		assertMintedHashes(labels);
	}

	private void assertMintedHashes(List<String> labels) throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(directory.resolve("wal"))
				.storeUuid("utf8-hash-test")
				.build();
		// Capture the public WAL append boundary: malformed UTF-16 tests hash compatibility independently of JSON
		// encoding.
		ValueStoreWAL wal = mock(ValueStoreWAL.class);
		when(wal.config()).thenReturn(config);
		AtomicInteger checked = new AtomicInteger();
		doAnswer(invocation -> {
			int id = invocation.getArgument(0);
			ValueStoreWalValueKind kind = invocation.getArgument(1);
			String lexical = invocation.getArgument(2);
			String datatype = invocation.getArgument(3);
			String language = invocation.getArgument(4);
			int hash = invocation.getArgument(5);
			assertThat(hash).as("UTF-8 WAL hash for value ID %s (%s)", id, kind)
					.isEqualTo(referenceHash(kind, lexical, datatype, language));
			return (long) checked.incrementAndGet();
		}).when(wal)
				.logMint(anyInt(), any(ValueStoreWalValueKind.class), anyString(), anyString(), anyString(), anyInt());

		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI datatype = vf.createIRI("http://example.org/" + "\u00e9".repeat(4_097) + "/datatype");
		try (ValueStore store = new ValueStore(values.toFile(), false, ValueStore.VALUE_CACHE_SIZE,
				ValueStore.VALUE_ID_CACHE_SIZE, ValueStore.NAMESPACE_CACHE_SIZE, ValueStore.NAMESPACE_ID_CACHE_SIZE,
				wal)) {
			for (String label : labels) {
				store.storeValue(vf.createLiteral(label, datatype));
			}
		}
		assertThat(checked.get()).isGreaterThanOrEqualTo(labels.size());
	}

	private static int referenceHash(ValueStoreWalValueKind kind, String lexical, String datatype, String language) {
		CRC32C crc = new CRC32C();
		crc.update((byte) kind.code());
		update(crc, lexical);
		crc.update(0);
		update(crc, datatype);
		crc.update(0);
		update(crc, language);
		return (int) crc.getValue();
	}

	private static void update(CRC32C crc, String value) {
		byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
		crc.update(bytes, 0, bytes.length);
	}
}
